{
  "positionId": "P01",
  "interviews": [
    {
      "categoryId": "P01-C2",
      "itemId": "P01-C2-I1",
      "interviewBlueprint": {
        "questionIntent": "실행 계획에서 확인한 병목을 쿼리 개선 방법과 연결할 수 있는지 검증한다. 인덱스 추가와 조인 정리를 선택한 근거가 실제 조회 조건과 실행 계획에 맞는지에 초점을 둔다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "포켓마켓 운영 화면의 신고 목록 조회 쿼리가 3.2초 걸렸다.",
          "task": "신고 목록 조회 쿼리의 실행 계획을 확인하고 인덱스 추가와 조인 정리로 조회 시간을 줄였다.",
          "action": "실행 계획과 조회 조건에서 확인한 정보를 인덱스 추가와 조인 정리의 선택 근거로 설명한다.",
          "result": "조회 시간이 3.2초에서 0.4초로 줄어든 결과를 해당 개선 판단과 연결해 설명한다."
        },
        "expectedEvidence": [
          "인덱스 추가와 조인 정리를 선택한 근거",
          "근거로 삼은 실행 계획의 특징과 조회 조건",
          "선택한 조치가 확인한 병목을 줄이는 이유"
        ]
      },
      "question": "포켓마켓에서 신고 목록 조회 쿼리를 3.2초에서 0.4초로 줄이셨을 때, 실행 계획을 보고 인덱스 추가와 조인 정리를 선택한 근거는 무엇이었나요?",
      "answerTip": "핵심 답변을 먼저 말한 뒤 풀어 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "실행 계획에서 확인한 병목을 근거로 인덱스 추가와 조인 정리를 선택한 이유를 구체적으로 설명한다.",
            "조회 조건과 테이블 접근 또는 조인 특성을 연결해 선택한 조치가 불필요한 작업을 줄이는 이유를 타당하게 설명한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "실행 계획이나 조회 조건을 선택 근거로 제시하지만 확인한 병목의 설명이 포괄적이다.",
            "인덱스 추가와 조인 정리가 조회 속도에 도움이 된다고 설명하지만 해당 쿼리와의 연결이 일부 부족하다."
          ]
        },
        "poor": {
          "criteria": [
            "선택 근거 대신 적용한 조치나 0.4초라는 결과만 반복한다.",
            "실행 계획에서 확인한 병목과 무관한 일반론을 제시하거나 개선 효과를 설명하는 논리가 맞지 않는다."
          ]
        }
      }
    },
    {
      "categoryId": "P01-C2",
      "itemId": "P01-C2-I2",
      "interviewBlueprint": {
        "questionIntent": "로그로 좁힌 장애 원인을 재발 방지 조치에 연결할 수 있는지 검증한다. 알림 중복 발송의 원인을 근거로 배포 체크리스트에 스케줄러 항목을 넣은 판단에 초점을 둔다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "포켓마켓에서 배포 다음 날 같은 알림이 두 번 발송된다는 문의를 받았다.",
          "task": "로그를 시간순으로 확인해 서버 두 대에서 스케줄러가 동시에 실행되는 원인을 찾았고, 잠금 키를 두는 방식으로 수정한 뒤 배포 체크리스트에 스케줄러 항목을 넣었다.",
          "action": "로그에서 확인한 중복 실행을 배포 체크리스트의 스케줄러 항목 추가 근거와 연결해 설명한다.",
          "result": "체크리스트 항목이 같은 원인의 반복 위험을 줄인다고 판단한 이유를 설명한다."
        },
        "expectedEvidence": [
          "재발 방지로 스케줄러 항목을 배포 체크리스트에 넣은 근거",
          "시간순 로그에서 확인한 두 서버의 스케줄러 동시 실행",
          "확인한 장애 원인과 체크리스트 항목의 연결"
        ]
      },
      "question": "포켓마켓에서 알림 중복 발송을 로그로 추적하셨을 때, 재발 방지로 배포 체크리스트에 스케줄러 항목을 넣은 근거는 무엇이었나요?",
      "answerTip": "핵심 답변을 먼저 말한 뒤 풀어 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "시간순 로그에서 확인한 두 서버의 스케줄러 동시 실행을 체크리스트 항목 추가의 구체적인 근거로 설명한다.",
            "스케줄러 항목이 확인한 중복 실행 원인의 반복 위험과 어떤 관련이 있는지 타당하게 설명한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "스케줄러 중복 실행을 체크리스트 항목 추가의 근거로 제시하지만 로그에서 확인한 정보는 구체적이지 않다.",
            "체크리스트가 재발 방지에 도움이 된다고 설명하지만 확인한 원인과의 연결이 일부 부족하다."
          ]
        },
        "poor": {
          "criteria": [
            "체크리스트에 항목을 넣은 근거를 설명하지 않고 잠금 키로 수정했다는 조치만 반복한다.",
            "로그로 확인한 원인과 연결하지 못한 채 체크리스트는 중요하다는 일반론이나 무관한 설명에 머문다."
          ]
        }
      }
    }
  ]
}

{
  "positionId": "P02",
  "interviews": [
    {
      "categoryId": "P02-C1",
      "itemId": "P02-C1-I1",
      "interviewBlueprint": {
        "questionIntent": "요청의 목적과 범위를 정리해 구현 범위를 합의할 수 있는지 확인한다. 세탁소 인터뷰에서 얻은 요구가 요구사항 정의서의 포함·제외 판단으로 이어진 근거에 초점을 둔다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "동네 세탁소 예약 서비스 기획은 플랜업스쿨 서비스 기획 과정의 팀 프로젝트였다.",
          "task": "기획 담당으로 세탁소 5곳을 인터뷰해 요구사항 정의서를 작성하고 개발 담당 팀원과 범위를 조정했다.",
          "action": "요구사항 정의서에 넣을 것과 뺄 것을 정한 근거를 인터뷰에서 파악한 목적과 연결해 설명한다.",
          "result": "그 근거가 개발 담당 팀원과 조정한 요구사항 범위에 어떻게 반영됐는지 설명한다."
        },
        "expectedEvidence": [
          "요구사항 정의서에 넣을 것과 뺄 것을 정한 구체적인 근거",
          "판단을 뒷받침한 세탁소 인터뷰의 요청과 목적",
          "판단 근거와 실제 조정한 범위의 연결"
        ]
      },
      "question": "동네 세탁소 예약 서비스 기획에서 개발 담당 팀원과 범위를 조정하셨을 때, 요구사항 정의서에 넣을 것과 뺄 것을 정한 근거는 무엇이었나요?",
      "answerTip": "구체적인 사례 하나로 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "포함·제외 판단의 근거를 세탁소 인터뷰에서 파악한 요청의 목적과 연결해 구체적으로 설명한다.",
            "그 근거로 요구사항의 우선순위나 경계를 구분한 내용을 제시해 개발 담당 팀원과 조정한 범위가 납득된다."
          ]
        },
        "acceptable": {
          "criteria": [
            "포함·제외 판단의 근거를 제시하지만 사용자 필요나 구현 여건 등 일반적인 설명에 머문다.",
            "조정한 범위는 언급하지만 인터뷰의 요청과 범위 판단 사이의 연결이 일부 불분명하다."
          ]
        },
        "poor": {
          "criteria": [
            "요구사항을 넣거나 뺀 판단 근거 없이 문서 작성 항목이나 작업 순서만 나열한다.",
            "개발 담당 팀원의 결정을 따랐다는 설명에 그쳐 본인의 범위 판단을 확인할 수 없다."
          ]
        }
      }
    },
    {
      "categoryId": "P02-C1",
      "itemId": "P02-C1-I2",
      "interviewBlueprint": {
        "questionIntent": "예외 상황을 화면 단위의 흐름으로 구체화할 수 있는지 확인한다. 화면설계서에서 예외 상황에 따른 화면 흐름을 설계한 판단 근거에 초점을 둔다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "동네 세탁소 예약 서비스 기획에서 예약·취소·알림 흐름과 예외 상황을 포함한 화면설계서를 작성했다.",
          "task": "기획 담당으로 Figma를 사용해 화면설계서 28장을 작성했다.",
          "action": "화면설계서에 담은 예외 상황 하나를 짚고 해당 상황의 화면 흐름을 설계한 근거를 설명한다.",
          "result": "설계 근거가 예외 상황에서의 화면 상태나 이동 흐름에 어떻게 반영됐는지 설명한다."
        },
        "expectedEvidence": [
          "예외 상황의 화면 흐름을 설계한 구체적인 근거",
          "그 근거와 연결되는 예약·취소·알림 중 한 예외 상황",
          "해당 예외 상황에 따른 화면 상태나 이동 흐름"
        ]
      },
      "question": "동네 세탁소 예약 서비스 기획에서 화면설계서 28장을 작성하셨을 때, 예외 상황의 화면 흐름을 설계한 근거는 무엇이었나요?",
      "answerTip": "직접 하신 일을 중심으로 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "화면설계서에 담은 구체적인 예외 상황과 연결해 화면 흐름을 설계한 근거를 설명한다.",
            "설계 근거와 화면 상태 또는 이동 흐름의 연결이 명확해 개발자와 디자이너가 구현할 동작을 이해할 수 있다."
          ]
        },
        "acceptable": {
          "criteria": [
            "예외 상황의 화면 흐름을 설계한 근거를 제시하지만 사용자 편의나 혼란 방지 등 일반적인 설명에 머문다.",
            "예외 상황과 화면 흐름을 언급하지만 그 흐름을 선택한 근거와의 연결이 일부 불분명하다."
          ]
        },
        "poor": {
          "criteria": [
            "예외 상황의 화면 흐름을 설계한 근거 없이 화면 수나 Figma 사용 기능만 설명한다.",
            "정상 흐름이나 화면의 외형만 설명해 예외 상황에 따른 화면 흐름의 판단을 확인할 수 없다."
          ]
        }
      }
    }
  ]
}

{
  "positionId": "P03",
  "interviews": [
    {
      "categoryId": "P03-C1",
      "itemId": "P03-C1-I1",
      "interviewBlueprint": {
        "questionIntent": "처방이 의심스러울 때 투약을 멈추고 담당자에게 확인할 수 있는지 평가한다. 평소와 다른 진통제 용량을 투약 전 확인이 필요한 문제로 판단한 근거에 초점을 둔다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "푸른결종합병원 근무 2년 차에 수술 후 환자의 진통제 처방 용량이 평소 용량의 두 배로 들어왔다.",
          "task": "수술 후 환자의 투약을 맡았으며, 해당 처방의 투약을 멈추고 담당의에게 확인했다.",
          "action": "처방 용량에서 발견한 차이와 그 차이를 투약 전 담당의에게 확인해야 한다고 판단한 근거를 설명한다.",
          "result": "판단 근거가 처방의 불확실성을 해소하기 전 투약을 보류한 결정과 어떻게 연결되는지 설명한다."
        },
        "expectedEvidence": [
          "진통제 처방 용량을 담당의에게 확인해야 한다고 판단한 근거",
          "평소 용량과 해당 처방 용량의 차이",
          "용량 차이를 확인 없이 투약해서는 안 된다고 본 이유"
        ]
      },
      "question": "푸른결종합병원에서 수술 후 환자의 진통제 투약을 멈추셨을 때, 처방 용량을 담당의에게 확인해야 한다고 판단한 근거는 무엇이었나요?",
      "answerTip": "당시 경험을 떠올리며 차분히 말해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "평소 용량의 두 배로 들어온 처방에서 무엇을 의심했는지 구체적으로 설명한다.",
            "평소와 다르다는 이유만으로 오류를 단정하지 않고, 처방의 적절성을 확인하기 전 투약을 보류해야 한다는 판단 근거를 설명한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "처방 용량이 평소와 달라 담당의 확인이 필요했다고 답하지만, 의심한 지점에 대한 설명은 제한적이다.",
            "환자 안전이나 처방 확인의 필요성을 근거로 들지만, 해당 용량 차이와 투약 보류 판단의 연결은 일반적이다."
          ]
        },
        "poor": {
          "criteria": [
            "투약을 멈추고 담당의에게 확인했다는 행동만 반복하고 판단 근거를 설명하지 못한다.",
            "나중에 입력 오류로 밝혀졌다는 결과만 제시하거나, 평소와 다른 처방은 모두 오류라는 설명으로 판단 근거를 대신한다."
          ]
        }
      }
    },
    {
      "categoryId": "P03-C1",
      "itemId": "P03-C1-I2",
      "interviewBlueprint": {
        "questionIntent": "관찰한 환자 상태 변화를 정확한 기록과 인수인계·보고로 연결할 수 있는지 평가한다. 직접 수행한 관찰·기록 경험에서 어떤 관찰 근거로 전달할 내용을 판단했는지에 초점을 둔다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "푸른결종합병원 정형외과 병동에서 수술 전후 환자의 활력징후와 통증을 관찰하고 기록했다.",
